<?php
namespace App\Services;
use App\Models\{Reservation,Room,FolioCharge,Payment,AuditEntry,Guest,User};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class HotelService {
 public static function fail(string $message): never {throw ValidationException::withMessages(['transaction'=>$message]);}
 public static function audit(string $action,string $subject,array $details=[]):void {AuditEntry::create(['user_id'=>auth()->id(),'action'=>$action,'subject'=>$subject,'details'=>$details]);}
 public static function folio(Reservation $r):array {$charges=$r->charges()->get();$payments=$r->payments()->get();$total=round((float)$r->amount+$charges->sum('amount'),2);$paid=round($payments->whereIn('kind',['Payment','Transfer In'])->sum('amount')-$payments->whereIn('kind',['Refund','Transfer Out'])->sum('amount'),2);return ['reservation'=>$r->load('guest','type','room.type'),'charges'=>$charges,'payments'=>$payments,'total'=>$total,'paid'=>$paid,'balance'=>round($total-$paid,2)];}
 public static function book(array $v, int $guestId, bool $staff):Reservation {return DB::transaction(function()use($v,$guestId,$staff){$room=Room::with('type')->lockForUpdate()->findOrFail($v['room_id']);if($room->out_of_service)self::fail('Room is out of service.');if($v['guest_count']>$room->type->capacity)self::fail('Guest count exceeds room capacity.');$overlap=Reservation::where('room_id',$room->id)->whereNotIn('status',['Cancelled','Checked-out'])->where('arrival','<',$v['departure'])->where('departure','>',$v['arrival'])->exists();if($overlap)self::fail('Room is no longer available for these dates.');$nights=\Carbon\Carbon::parse($v['arrival'])->diffInDays(\Carbon\Carbon::parse($v['departure']));$rate=(float)$room->type->rate;$user=auth()->user();$points=0;if(!$staff && !empty($v['pay_with_points'])){$account=User::lockForUpdate()->findOrFail($user->id);$points=$room->type->points_per_night*$nights;if($points<=0||$account->points<$points)self::fail('Insufficient points or room is not eligible for redemption.');$account->decrement('points',$points);$rate=0;}elseif($user?->role==='guest' && $user->points>=500)$rate*=.8;$r=Reservation::create(['code'=>'HTL-'.strtoupper(bin2hex(random_bytes(5))),'guest_id'=>$guestId,'payer_guest_id'=>$staff?($v['payer_guest_id']??$guestId):$guestId,'room_id'=>$room->id,'arrival'=>$v['arrival'],'departure'=>$v['departure'],'guest_count'=>$v['guest_count'],'amount'=>round($rate*$nights,2),'points_redeemed'=>$points,'requests'=>$v['requests']??null]);$occupants=$staff?array_unique($v['occupant_ids']??[$guestId]):[$guestId];foreach($occupants as $id)$r->occupants()->attach($id);self::audit('reservation.created',$r->code);return $r;});}
 public static function checkIn(Reservation $r):Reservation {return DB::transaction(function()use($r){$r=Reservation::lockForUpdate()->findOrFail($r->id);if(!$r->room_id)self::fail('Hotel Staff must assign a room at check-in.');$room=Room::lockForUpdate()->findOrFail($r->room_id);if($r->status!=='Confirmed')self::fail('Only confirmed reservations may check in.');if($r->arrival>today()->toDateString() || $r->departure<=today()->toDateString())self::fail('Reservation is outside its arrival window.');if($room->out_of_service || !in_array($room->housekeeping_status,['Clean','Inspected']))self::fail('Room is not ready.');if(Reservation::where('room_id',$room->id)->where('status','Checked-in')->where('id','!=',$r->id)->exists())self::fail('Room is occupied.');if(!$r->occupants()->exists())self::fail('Registration requires at least one occupant.');$r->update(['status'=>'Checked-in','checked_in_at'=>now()]);self::audit('reservation.checked-in',$r->code);return $r;});}
 public static function checkout(Reservation $r):Reservation {return DB::transaction(function()use($r){$r=Reservation::lockForUpdate()->findOrFail($r->id);if($r->status!=='Checked-in')self::fail('Only an active stay may check out.');BillAcknowledgment::require('Hotel',$r->id);if(abs(self::folio($r)['balance'])>.005)self::fail('Resolve outstanding or credit balances before checkout.');$r->update(['status'=>'Checked-out','checked_out_at'=>now()]);$r->room()->update(['housekeeping_status'=>'Dirty']);if(!$r->points_redeemed)User::where('guest_id',$r->guest_id)->increment('points',(int)floor(self::folio($r)['total']/100));self::audit('reservation.checked-out',$r->code);return $r;});}
}
